import{_ as i,a0 as l,w as p,s as d,I as e,x as s,a1 as t,A as o,ao as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const f=JSON.parse('{"title":"在 Linux 上使用 jps 命令檢查 Java 進程 | LCTT x X-CMD","titleTemplate":false,"description":"在 Linux 上使用 jps 命令檢查 Java 進程 | LCTT (202110) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Linux 上使用 jps 命令檢查 Java 進程 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Linux 上使用 jps 命令檢查 Java 進程 | LCTT (202110) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202110/20211006 Check Java processes on Linux with the jps command","title":"在 Linux 上使用 jps 命令檢查 Java 進程","tag":"202110","desc":""},"relativePath":"202110/20211006 Check Java processes on Linux with the jps command.md","filePath":"[post].md"}'),u={name:"202110/20211006 Check Java processes on Linux with the jps command.md"};function g(m,a,v,j,b,h){const n=l("Link");return p(),d("div",null,[a[18]||(a[18]=e("h1",{id:"在-linux-上使用-jps-命令檢查-java-進程",tabindex:"-1"},[s("在 Linux 上使用 jps 命令檢查 Java 進程 "),e("a",{class:"header-anchor",href:"#在-linux-上使用-jps-命令檢查-java-進程","aria-label":"Permalink to “在 Linux 上使用 jps 命令檢查 Java 進程”"},"​")],-1)),a[19]||(a[19]=e("blockquote",null,[e("p",null,[s("系統上運行着諸多進程，通過 "),e("code",null,"jps"),s(" 命令能夠快速有效識別 Java 進程。")])],-1)),a[20]||(a[20]=e("p",null,[e("img",{src:"https://img.linux.net.cn/data/attachment/album/202110/11/102806lhhtyalq2lv2vbte.jpg",alt:""})],-1)),e("p",null,[a[1]||(a[1]=s("在 Linux 中，有一些用於查看系統上運行進程的命令。進程是指由內核管理的正在進行的事件。每啓動一個應用程序時，就會產生一個進程，但也有許多在計算機後台運行的進程，如保持系統時間準確的進程、監聽新文件系統的進程、索引化文件的進程等。有一些可以用來監測這些進程的實用程序，比如包含在 ",-1)),t(n,{href:"https://opensource.com/article/21/8/linux-procps-ng"},{default:o(()=>[...a[0]||(a[0]=[s("procps-ng 包",-1)])]),_:1}),a[2]||(a[2]=s(" 中的程序，但它們往往都是對各種進程通用的。它們會查看計算機上的所有進程，你可以根據需要過濾結果列表。",-1))]),a[21]||(a[21]=r(`<p>在 Linux 中，可以通過 <code>ps</code> 命令查看進程。這是查看當前系統上運行進程最簡單的方法。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ps</span></span>
<span class="line"><span>    PID TTY          TIME CMD</span></span>
<span class="line"><span>   4486 pts/0    00:00:00 bash</span></span>
<span class="line"><span>  66930 pts/0    00:00:00 ps</span></span></code></pre></div><p>你也可以通過 <code>ps</code> 命令，並配合結果輸出管道符進行 <code>grep</code>，從而查看系統上運行的 Java 進程，。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ps ax |grep java</span></span>
<span class="line"><span>  67604 pts/1    Sl+    0:18 /usr/lib/jvm/java-11-openjdk-11.0.12.0.7-4.fc34.x86_64/bin/java -D[Standalone] -server -Xms64m -Xmx512m -XX:MetaspaceSize=96M -XX:MaxMetaspaceSize=256m -Djava.net.preferIPv4Stack=true -Djboss.modules.system.pkgs=org.jboss.byteman -Djava.awt.headless=true --add-exports=java.desktop/sun.awt=ALL-UNNAMED --add-exports=java.naming/com.sun.jndi.ldap=ALL-UNNAMED --add-opens=java.base/java.lang=ALL-UNNAMED --add-opens=java.base/java.lang.invoke=ALL-UNNAMED --add-opens=java.base/java.io=ALL-UNNAMED --add-opens=java.base/java.security=ALL-UNNAMED --add-opens=java.base/java.util=ALL-UNNAMED --add-opens=java.management/javax.management=ALL-UNNAMED --add-opens=java.naming/javax.naming=ALL-UNNAMED -Dorg.jboss.boot.log.file=/home/alan/wildfly/24.0.1/standalone/log/server.log -Dlogging.configuration=file:/home/alan/wildfly/24.0.1/standalone/configuration/logging.properties -jar /home/alan/wildfly/24.0.1/jboss-modules.jar -mp /home/alan/wildfly/24.0.1/modules org.jboss.as.standalone -Djboss.home.dir=/home/alan/wildfly/24.0.1 -Djboss.server.base.dir=/home/alan/wildfly/24.0.1/standalone</span></span></code></pre></div><p>然而，OpenJDK 有自己專屬的進程監視器。<ruby>Java 虛擬機進程狀態<rt>Java Virtual Machine Process Status</rt></ruby>（jps）工具可以幫你掃描系統上所有運行的 Java 虛擬機（JVM）實例。</p><p>要想實現與 <code>ps</code> 命令類似的輸出，可以使用 <code>-v</code> 選項。這很實用，這與 <code>ps</code> 相比，可以減少你的輸入。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ jps -v</span></span>
<span class="line"><span>67604 jboss-modules.jar -D[Standalone] -Xms64m -Xmx512m -XX:MetaspaceSize=96M -XX:MaxMetaspaceSize=256m -Djava.net.preferIPv4Stack=true -Djboss.modules.system.pkgs=org.jboss.byteman -Djava.awt.headless=true --add-exports=java.desktop/sun.awt=ALL-UNNAMED --add-exports=java.naming/com.sun.jndi.ldap=ALL-UNNAMED --add-opens=java.base/java.lang=ALL-UNNAMED --add-opens=java.base/java.lang.invoke=ALL-UNNAMED --add-opens=java.base/java.io=ALL-UNNAMED --add-opens=java.base/java.security=ALL-UNNAMED --add-opens=java.base/java.util=ALL-UNNAMED --add-opens=java.management/javax.management=ALL-UNNAMED --add-opens=java.naming/javax.naming=ALL-UNNAMED -Dorg.jboss.boot.log.file=/home/alan/wildfly/24.0.1/standalone/log/server.log -Dlogging.configuration=file:/home/alan/wildfly/24.0.1/standalone/configuration/logging.properties</span></span></code></pre></div><p><code>jps</code> 命令的默認輸出包含進程標識符，類名或 Jar 文件名。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ jps</span></span>
<span class="line"><span>67604 jboss-modules.jar</span></span>
<span class="line"><span>69430 Jps</span></span></code></pre></div><p><strong>注意：</strong> <code>jps</code> 的手冊頁指出此命令是試驗性且不受支持的。儘管如此，它仍然是一個不錯的選擇，因為一個系統通常運行着許多進程，這種只識別 Java 進程的快速方法是很有用的。</p><p>當下的 Java 仍然是一種流行的語言，所以熟悉 Java 開發工具包和運行時環境仍然很重要。它們包含着許多適用於 Java 應用程序開發和維護的工具。</p><hr>`,12)),e("p",null,[a[4]||(a[4]=s("via: ",-1)),t(n,{href:"https://opensource.com/article/21/10/check-java-jps"},{default:o(()=>[...a[3]||(a[3]=[s("https://opensource.com/article/21/10/check-java-jps",-1)])]),_:1})]),e("p",null,[a[9]||(a[9]=s("作者：",-1)),t(n,{href:"https://opensource.com/users/alanfdoss"},{default:o(()=>[...a[5]||(a[5]=[s("Alan Formy-Duval",-1)])]),_:1}),a[10]||(a[10]=s(" 選題：",-1)),t(n,{href:"https://github.com/lujun9972"},{default:o(()=>[...a[6]||(a[6]=[s("lujun9972",-1)])]),_:1}),a[11]||(a[11]=s(" 譯者：",-1)),t(n,{href:"https://github.com/unigeorge"},{default:o(()=>[...a[7]||(a[7]=[s("unigeorge",-1)])]),_:1}),a[12]||(a[12]=s(" 校對：",-1)),t(n,{href:"https://github.com/turbokernel"},{default:o(()=>[...a[8]||(a[8]=[s("turbokernel",-1)])]),_:1})]),e("p",null,[a[15]||(a[15]=s("本文由 ",-1)),t(n,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...a[13]||(a[13]=[s("LCTT",-1)])]),_:1}),a[16]||(a[16]=s(" 原創編譯，",-1)),t(n,{href:"https://linux.cn/"},{default:o(()=>[...a[14]||(a[14]=[s("Linux中國",-1)])]),_:1}),a[17]||(a[17]=s(" 榮譽推出",-1))])])}const c=i(u,[["render",g]]);export{f as __pageData,c as default};
